module.exports = drive_link

// dat://<length>.<fork>.<key>.<hash>/<path>?<env>#<arg>
// shorter forms: dat://<key>, dat://<fork>.<key>, dat://<length>.<fork>.<key>
function drive_link () {
  const api = { encode, decode }
  return api
}

/***************************************
ENCODE
{ key: [length, fork, key, hash], path, env, arg } -> href
***************************************/
function encode ({ key, path = '', env = {}, arg = {} }) {
  const search = `${new URLSearchParams(env)}`
  const hash = `${new URLSearchParams(arg)}`
  const slash = path && !path.startsWith('/') ? '/' : ''
  return `dat://${to_host(key)}${slash}${encodeURI(path).replace(/[?#]/g, encodeURIComponent)}${search && '?' + search}${hash && '#' + hash}`
}

/***************************************
DECODE
href -> { key: [length, fork, key, hash], path, env, arg }
***************************************/
function decode (href) {
  const url = new URL(href)
  if (url.protocol !== 'dat:') throw new Error(`invalid link: ${href}`)
  const env = Object.fromEntries(new URLSearchParams(url.search))
  const arg = Object.fromEntries(new URLSearchParams(url.hash.slice(1)))
  return { key: to_key(url.hostname), path: decodeURIComponent(url.pathname), env, arg }
}

/***************************************
TO HOST
[length, fork, key, hash] -> "length.fork.key.hash", leaving out empty parts at the start and an empty hash
***************************************/
function to_host (key) {
  const parts = [0, 1, 2, 3].map(i => `${key[i] ?? ''}`)
  const start = parts.findIndex(x => x)
  const end = parts[3] ? 4 : 3
  const host = parts.slice(start, end)
  if (!parts[2] || host.some(x => !x) || (end === 4 && start !== 0)) throw new Error(`invalid link key: ${key}`)
  return host.join('.')
}

/***************************************
TO KEY
"length.fork.key.hash" or a shorter form -> [length, fork, key, hash]
***************************************/
function to_key (host) {
  const parts = host.split('.')
  if (parts.some(x => !x)) throw new Error(`invalid link: ${host}`)
  const [length, fork, key, hash] = parts
  switch (parts.length) {
  case 1: return ['', '', length, '']
  case 2: return ['', length, fork, '']
  case 3: return [length, fork, key, '']
  case 4: return [length, fork, key, hash]
  }
  throw new Error(`invalid link: ${host}`)
}
